        }))
    : undefined;

  return {
    id: typeof data.id === "string" ? data.id : id,
    title: typeof data.title === "string" ? data.title : "",
    status: typeof data.status === "string" ? data.status : "unknown",
    dependsOn: Array.isArray(data.depends_on)
      ? data.depends_on.filter((d) => typeof d === "string")
      : [],
    ...(data.execution?.actor_type
      ? {
          execution: {
            actor_type: data.execution.actor_type,
            ...(typeof data.execution.last_updated_by === "string"
              ? { last_updated_by: data.execution.last_updated_by }
              : {}),
            ...(typeof data.execution.last_updated_at === "string"
              ? { last_updated_at: data.execution.last_updated_at }
              : {}),
          },
        }
      : {}),
    ...(typeof data.branch === "string" ? { branch: data.branch } : {}),
    ...(data.pr !== undefined ? { pr: data.pr } : {}),
    ...(data.workspace_pr !== undefined ? { workspace_pr: data.workspace_pr } : {}),
    ...(typeof data.blocked_reason === "string" && data.blocked_reason !== null
      ? { blockedReason: data.blocked_reason }
      : {}),
    ...(log !== undefined ? { log } : {}),
  };
}
EOF

echo "yaml-parser.ts written"

# Now update the test file to add the new test case
# First read current test file and find insertion point
TESTFILE="src/__tests__/yaml-parser.test.ts"
TMPFILE="/tmp/yaml-parser.test.ts.new"

# Use awk to insert the new test before the "parses pr and workspace_pr" test
awk '
/it\("parses pr and workspace_pr as separate top-level fields"/ {
  print "  it(\"parses execution with last_updated_by and last_updated_at fields\", () => {"
  print "    const raw = `"
  print "id: T2"
  print "title: GitHub Contents API client"
  print "status: in_review"
  print "depends_on: []"
  print "execution:"
  print "  actor_type: agent"
  print "  last_updated_by: user@example.com"
  print "  last_updated_at: \"2026-05-05T09:36:54.679Z\""
  print "`;"
  print "    const task = parseTaskYaml(\"T2\", raw);"
  print "    expect(task).not.toBeNull();"
  print "    expect(task!.execution?.actor_type).toBe(\"agent\");"
  print "    expect(task!.execution?.last_updated_by).toBe(\"user@example.com\");"
  print "    expect(task!.execution?.last_updated_at).toBe(\"2026-05-05T09:36:54.679Z\");"
  print "  });"
  print ""
}
{ print }
' "$TESTFILE" > "$TMPFILE"

mv "$TMPFILE" "$TESTFILE"
echo "test file updated"

# Verify our changes
echo "=== yaml-parser.ts execution type changes ==="
grep -n "execution" src/services/yaml-parser.ts | head -10

echo "=== test file new test ==="
grep -n "last_updated" src/__tests__/yaml-parser.test.ts | head -5

# Stage and commit
git add src/services/yaml-parser.ts src/__tests__/yaml-parser.test.ts
git status --short
git commit -m "fix: add last_updated_by and last_updated_at to execution type in yaml-parser"
echo "=== COMMITTED ===" && git log --oneline -3

